// Extended oscillator: Eight waveforms, drive, unison and additive rendering.
// Audition composition of public Rust primitives; not an instrument parity claim.
// Examples name imports so you can trace each tool to its module.
// Alternative: import * as manifold from '@manifold/author';
// Then use manifold.createGraphWorkspace(), manifold.gain, etc.
// Imports — each definition can be inspected in Manifold's primitive catalog.
import { createGraphWorkspace } from '@manifold/author';
import {
  extendedOscillator as extendedOscillatorDefinition,
} from '@manifold/author/primitives';

export default function createProject() {
  // Interface — public paths and stable IDs preserve saved controls.
  const controls = {
    extendedOscillator_waveform: {
      "path": "/primitives/extended-oscillator/node/0",
      "label": "Waveform",
      "group": "Extended oscillator",
      "min": 0,
      "max": 7,
      "default": 1,
      "choices": [
        "Sine",
        "Saw",
        "Square",
        "Triangle",
        "Blend",
        "Noise",
        "Pulse",
        "Supersaw"
      ]
    },
    extendedOscillator_frequency: {
      "path": "/primitives/extended-oscillator/node/1",
      "label": "Frequency",
      "group": "Extended oscillator",
      "min": 20,
      "max": 16000,
      "default": 220
    },
    extendedOscillator_level: {
      "path": "/primitives/extended-oscillator/node/2",
      "label": "Level",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 0.16
    },
    extendedOscillator_syncEnabled: {
      "path": "/primitives/extended-oscillator/node/3",
      "label": "Sync enabled",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 0,
      "choices": [
        "Free",
        "Sync"
      ]
    },
    extendedOscillator_pulseWidth: {
      "path": "/primitives/extended-oscillator/node/4",
      "label": "Pulse width",
      "group": "Extended oscillator",
      "min": 0.01,
      "max": 0.99,
      "default": 0.5
    },
    extendedOscillator_drive: {
      "path": "/primitives/extended-oscillator/node/5",
      "label": "Drive",
      "group": "Extended oscillator",
      "min": 0,
      "max": 20,
      "default": 0
    },
    extendedOscillator_driveShape: {
      "path": "/primitives/extended-oscillator/node/6",
      "label": "Drive shape",
      "group": "Extended oscillator",
      "min": 0,
      "max": 3,
      "default": 0,
      "choices": [
        "Tanh",
        "Atan",
        "Clip",
        "Fold"
      ]
    },
    extendedOscillator_driveBias: {
      "path": "/primitives/extended-oscillator/node/7",
      "label": "Drive bias",
      "group": "Extended oscillator",
      "min": -1,
      "max": 1,
      "default": 0
    },
    extendedOscillator_driveMix: {
      "path": "/primitives/extended-oscillator/node/8",
      "label": "Drive mix",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 1
    },
    extendedOscillator_retriggerOnLevelRise: {
      "path": "/primitives/extended-oscillator/node/9",
      "label": "Retrigger on level rise",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 0,
      "choices": [
        "Off",
        "On"
      ]
    },
    extendedOscillator_unisonVoices: {
      "path": "/primitives/extended-oscillator/node/10",
      "label": "Unison voices",
      "group": "Extended oscillator",
      "min": 1,
      "max": 8,
      "default": 1
    },
    extendedOscillator_detuneCents: {
      "path": "/primitives/extended-oscillator/node/11",
      "label": "Detune cents",
      "group": "Extended oscillator",
      "min": 0,
      "max": 100,
      "default": 0
    },
    extendedOscillator_stereoSpread: {
      "path": "/primitives/extended-oscillator/node/12",
      "label": "Stereo spread",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 0
    },
    extendedOscillator_renderMode: {
      "path": "/primitives/extended-oscillator/node/13",
      "label": "Render mode",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 0,
      "choices": [
        "Standard",
        "Additive"
      ]
    },
    extendedOscillator_additivePartials: {
      "path": "/primitives/extended-oscillator/node/14",
      "label": "Additive partials",
      "group": "Extended oscillator",
      "min": 1,
      "max": 32,
      "default": 8
    },
    extendedOscillator_additiveTilt: {
      "path": "/primitives/extended-oscillator/node/15",
      "label": "Additive tilt",
      "group": "Extended oscillator",
      "min": -1,
      "max": 1,
      "default": 0
    },
    extendedOscillator_additiveDrift: {
      "path": "/primitives/extended-oscillator/node/16",
      "label": "Additive drift",
      "group": "Extended oscillator",
      "min": 0,
      "max": 1,
      "default": 0
    },
  };

  // Audio inputs and outputs — generated sound; no audio input is needed.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // DSP instances — parameters belong to these named instances.
  const extendedOscillator = graph.add(extendedOscillatorDefinition.type, {"id":4});
  graph.registerInstance('/primitives/extended-oscillator/node', extendedOscillator);
  extendedOscillator.parameter('waveform').expose(controls.extendedOscillator_waveform);
  extendedOscillator.parameter('frequency').expose(controls.extendedOscillator_frequency);
  extendedOscillator.parameter('level').expose(controls.extendedOscillator_level);
  extendedOscillator.parameter('syncEnabled').expose(controls.extendedOscillator_syncEnabled);
  extendedOscillator.parameter('pulseWidth').expose(controls.extendedOscillator_pulseWidth);
  extendedOscillator.parameter('drive').expose(controls.extendedOscillator_drive);
  extendedOscillator.parameter('driveShape').expose(controls.extendedOscillator_driveShape);
  extendedOscillator.parameter('driveBias').expose(controls.extendedOscillator_driveBias);
  extendedOscillator.parameter('driveMix').expose(controls.extendedOscillator_driveMix);
  extendedOscillator.parameter('retriggerOnLevelRise').expose(controls.extendedOscillator_retriggerOnLevelRise);
  extendedOscillator.parameter('unisonVoices').expose(controls.extendedOscillator_unisonVoices);
  extendedOscillator.parameter('detuneCents').expose(controls.extendedOscillator_detuneCents);
  extendedOscillator.parameter('stereoSpread').expose(controls.extendedOscillator_stereoSpread);
  extendedOscillator.parameter('renderMode').expose(controls.extendedOscillator_renderMode);
  extendedOscillator.parameter('additivePartials').expose(controls.extendedOscillator_additivePartials);
  extendedOscillator.parameter('additiveTilt').expose(controls.extendedOscillator_additiveTilt);
  extendedOscillator.parameter('additiveDrift').expose(controls.extendedOscillator_additiveDrift);

  // Composition — named ports make the audio and control paths visible.
  graph.connect(extendedOscillator.output('out'), output);

  // Presentation — both renderers bind to the controls declared above.
  const view = [
    controls.extendedOscillator_waveform,
    controls.extendedOscillator_frequency,
    controls.extendedOscillator_level,
    controls.extendedOscillator_syncEnabled,
    controls.extendedOscillator_pulseWidth,
    controls.extendedOscillator_drive,
    controls.extendedOscillator_driveShape,
    controls.extendedOscillator_driveBias,
    controls.extendedOscillator_driveMix,
    controls.extendedOscillator_retriggerOnLevelRise,
    controls.extendedOscillator_unisonVoices,
    controls.extendedOscillator_detuneCents,
    controls.extendedOscillator_stereoSpread,
    controls.extendedOscillator_renderMode,
    controls.extendedOscillator_additivePartials,
    controls.extendedOscillator_additiveTilt,
    controls.extendedOscillator_additiveDrift
  ].map(control => ({
    id: control.path, type: 'parameter', path: control.path,
    label: control.label, group: control.group,
    ...(control.choices ? { choices: control.choices } : {}),
  }));
  function paint(ui) {
    for (const component of view) {
      if (component.type === 'label') ui.label(component.label, component.id);
      else ui.parameter(component.path, component);
    }
  }

  // The host uses this project declaration for audio, UI, save and live edits.
  return { graph, view, paint };
}
